-- =====================================================================
-- MediSlot RDS MySQL schema  (SCHEMA_VERSION 3, aligned to the project ER diagram)
-- Run by application/database/init_schema.py (idempotent: CREATE ... IF NOT EXISTS,
-- seed rows use ON DUPLICATE KEY UPDATE).
--
-- Deliberate differences from the ER picture (see docs/data_model/README.md):
--   * IDs are CHAR(36) UUIDs generated by the application (not BIGINT): they also
--     appear in JWT "sub" claims and DynamoDB keys.
--   * consultation_types has doctor_id (a doctor owns / edits only their own types).
--   * materialised_slots also stores start_utc, end_utc and timezone (UTC storage with
--     the originating timezone recorded, required by the brief).
-- =====================================================================
SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE IF NOT EXISTS users (
    user_id CHAR(36) NOT NULL,
    email VARCHAR(254) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role ENUM('PATIENT','DOCTOR') NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_users_email (email),
    KEY ix_users_role_active (role, is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS hospitals (
    hospital_id CHAR(36) NOT NULL,
    hospital_name VARCHAR(180) NOT NULL,
    address VARCHAR(255) NOT NULL,
    city VARCHAR(100) NOT NULL,
    phone VARCHAR(30) NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (hospital_id),
    KEY ix_hospitals_city_active (city, is_active),
    KEY ix_hospitals_name (hospital_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS specialisations (
    specialisation_id CHAR(36) NOT NULL,
    specialisation_name VARCHAR(120) NOT NULL,
    description TEXT NULL,
    PRIMARY KEY (specialisation_id),
    UNIQUE KEY uq_specialisations_name (specialisation_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS patients (
    patient_id CHAR(36) NOT NULL,
    user_id CHAR(36) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    date_of_birth DATE NULL,
    gender VARCHAR(30) NULL,
    phone VARCHAR(30) NULL,
    address TEXT NULL,
    city VARCHAR(100) NULL,
    emergency_contact VARCHAR(150) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (patient_id),
    UNIQUE KEY uq_patients_user (user_id),
    KEY ix_patients_name (last_name, first_name),
    CONSTRAINT fk_patients_user FOREIGN KEY (user_id) REFERENCES users(user_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS doctors (
    doctor_id CHAR(36) NOT NULL,
    user_id CHAR(36) NOT NULL,
    hospital_id CHAR(36) NOT NULL,
    specialisation_id CHAR(36) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    licence_number VARCHAR(50) NOT NULL,
    experience_years SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    qualifications TEXT NULL,
    photo_url VARCHAR(500) NULL COMMENT 'S3 object key of the profile photo (served via pre-signed GET)',
    timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata' COMMENT 'Doctor home timezone, IANA identifier',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (doctor_id),
    UNIQUE KEY uq_doctors_user (user_id),
    UNIQUE KEY uq_doctors_licence (licence_number),
    KEY ix_doctors_hospital_active (hospital_id, is_active),
    KEY ix_doctors_specialisation_active (specialisation_id, is_active),
    KEY ix_doctors_name (last_name, first_name),
    CONSTRAINT fk_doctors_user FOREIGN KEY (user_id) REFERENCES users(user_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_doctors_hospital FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_doctors_specialisation FOREIGN KEY (specialisation_id) REFERENCES specialisations(specialisation_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS consultation_types (
    consultation_type_id CHAR(36) NOT NULL,
    doctor_id CHAR(36) NOT NULL,
    type_name VARCHAR(100) NOT NULL,
    duration_minutes SMALLINT UNSIGNED NOT NULL,
    fee DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    PRIMARY KEY (consultation_type_id),
    UNIQUE KEY uq_consultation_type_doctor_name (doctor_id, type_name),
    CONSTRAINT fk_consultation_types_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT chk_consultation_duration CHECK (duration_minutes > 0),
    CONSTRAINT chk_consultation_fee CHECK (fee >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS availability_patterns (
    availability_id CHAR(36) NOT NULL,
    doctor_id CHAR(36) NOT NULL,
    consultation_type_id CHAR(36) NOT NULL,
    day_of_week TINYINT UNSIGNED NOT NULL COMMENT 'ISO weekday: Monday=1 ... Sunday=7',
    start_time TIME NOT NULL COMMENT 'Local time in the doctor timezone',
    end_time TIME NOT NULL COMMENT 'Local time in the doctor timezone',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    capacity SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    PRIMARY KEY (availability_id),
    KEY ix_availability_doctor_day_active (doctor_id, day_of_week, is_active),
    KEY ix_availability_consultation_type (consultation_type_id),
    CONSTRAINT fk_availability_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_availability_consultation_type FOREIGN KEY (consultation_type_id) REFERENCES consultation_types(consultation_type_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT chk_availability_day CHECK (day_of_week BETWEEN 1 AND 7),
    CONSTRAINT chk_availability_time CHECK (end_time > start_time),
    CONSTRAINT chk_availability_capacity CHECK (capacity BETWEEN 1 AND 10)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS blackout_dates (
    blackout_id CHAR(36) NOT NULL,
    doctor_id CHAR(36) NOT NULL,
    blackout_date DATE NOT NULL,
    reason VARCHAR(255) NULL,
    PRIMARY KEY (blackout_id),
    UNIQUE KEY uq_blackout_doctor_date (doctor_id, blackout_date),
    CONSTRAINT fk_blackout_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS materialised_slots (
    slot_id VARCHAR(160) NOT NULL COMMENT 'doctor_id#availability_id#startUTC - deterministic, makes materialisation idempotent',
    availability_id CHAR(36) NOT NULL COMMENT 'Source pattern (reference only, no FK: patterns can be replaced)',
    doctor_id CHAR(36) NOT NULL,
    consultation_type_id CHAR(36) NOT NULL,
    `date` DATE NOT NULL COMMENT 'Local calendar date in the doctor timezone',
    start_time TIME NOT NULL COMMENT 'Local start time',
    end_time TIME NOT NULL COMMENT 'Local end time',
    start_utc DATETIME NOT NULL,
    end_utc DATETIME NOT NULL,
    timezone VARCHAR(64) NOT NULL COMMENT 'Originating IANA timezone',
    capacity SMALLINT UNSIGNED NOT NULL,
    booked_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    status ENUM('OPEN','FULL','BLOCKED','CLOSED') NOT NULL DEFAULT 'OPEN',
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (slot_id),
    KEY ix_slots_doctor_date (doctor_id, `date`),
    KEY ix_slots_doctor_start (doctor_id, start_utc),
    KEY ix_slots_status_start (status, start_utc),
    CONSTRAINT fk_slots_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_slots_consultation_type FOREIGN KEY (consultation_type_id) REFERENCES consultation_types(consultation_type_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT chk_slots_time CHECK (end_utc > start_utc),
    CONSTRAINT chk_slots_capacity CHECK (booked_count <= capacity)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS appointments (
    appointment_id CHAR(36) NOT NULL,
    patient_id CHAR(36) NOT NULL,
    doctor_id CHAR(36) NOT NULL,
    slot_id VARCHAR(160) NOT NULL,
    consultation_type_id CHAR(36) NOT NULL,
    status ENUM('CONFIRMED','COMPLETED','CANCELLED_BY_PATIENT','CANCELLED_BY_DOCTOR','NO_SHOW') NOT NULL DEFAULT 'CONFIRMED',
    notes TEXT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (appointment_id),
    KEY ix_appointments_patient_status (patient_id, status),
    KEY ix_appointments_doctor_status (doctor_id, status),
    KEY ix_appointments_slot (slot_id),
    CONSTRAINT fk_appointments_patient FOREIGN KEY (patient_id) REFERENCES patients(patient_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_appointments_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_appointments_consultation_type FOREIGN KEY (consultation_type_id) REFERENCES consultation_types(consultation_type_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS refund_ledger (
    refund_id CHAR(36) NOT NULL,
    appointment_id CHAR(36) NOT NULL,
    refund_amount DECIMAL(10,2) NOT NULL,
    refund_percentage DECIMAL(5,2) NOT NULL,
    refund_status ENUM('CALCULATED','PENDING','PROCESSED','FAILED','NOT_APPLICABLE') NOT NULL DEFAULT 'CALCULATED',
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (refund_id),
    UNIQUE KEY uq_refund_appointment (appointment_id),
    CONSTRAINT fk_refund_appointment FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT chk_refund_amount CHECK (refund_amount >= 0),
    CONSTRAINT chk_refund_percentage CHECK (refund_percentage >= 0 AND refund_percentage <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- =====================================================================
-- DEVELOPMENT SEED DATA (idempotent: existing rows are never overwritten)
-- Accounts hold bcrypt hashes only (work factor 12); no plaintext passwords.
-- Doctor/consultation-type rows are looked up by account email, so the seed also works
-- if an account such as doctor1@example.com was registered through the API first.
-- =====================================================================
