INSERT INTO consultation_types (consultation_type_id, doctor_id, type_name, duration_minutes, fee)
SELECT t.ct_id, dr.doctor_id, t.ct_name, t.ct_minutes, t.ct_fee
FROM (
    SELECT 'c46b6593-3879-58a0-b758-c276c3225e90' AS ct_id, 'Quick Consult' AS ct_name, 15 AS ct_minutes, 400 AS ct_fee
    UNION ALL SELECT 'cbadb35a-17d1-50ec-ad09-39cdd10d8bc4' AS ct_id, 'Standard Consult' AS ct_name, 30 AS ct_minutes, 800 AS ct_fee
    UNION ALL SELECT '39a19693-b820-53cb-ae1c-fd75a4c0b58b' AS ct_id, 'Detailed Consult' AS ct_name, 60 AS ct_minutes, 1400 AS ct_fee
    UNION ALL SELECT 'aa9f22d7-afaf-5694-910f-0480623c5cec' AS ct_id, 'Health Camp Session' AS ct_name, 60 AS ct_minutes, 200 AS ct_fee
) t
JOIN users u ON u.email = 'doctor1@example.com' AND u.role = 'DOCTOR'
JOIN doctors dr ON dr.user_id = u.user_id
ON DUPLICATE KEY UPDATE consultation_type_id = consultation_type_id;

